<?php
function admin_appearance_get($userId){static $cache=[];if(isset($cache[$userId]))return $cache[$userId];try{$row=sc_query('SELECT * FROM admin_appearance WHERE user_id=?','i',[$userId])->get_result()->fetch_assoc();}catch(mysqli_sql_exception $e){$row=null;}return $cache[$userId]=$row?:['theme'=>'classic','accent'=>'#696cff','background_image'=>''];}
function admin_appearance_validate($theme,$accent){if(!in_array($theme,['classic','xp','midnight','forest','lavender','blood','chess','cartoon','doctor','aurora','sandstone','blueprint','botanical','neon'],true)||!preg_match('/^#[0-9a-f]{6}$/i',$accent))throw new RuntimeException('Choose a preset and a valid colour.');}
function admin_appearance_assets(){if(empty($_SESSION[USER_AUTH]))return '';$id=(int)getIdFromUserid($_SESSION[USER_AUTH]);$p=admin_appearance_get($id);$theme=in_array($p['theme'],['classic','xp','midnight','forest','lavender','blood','chess','cartoon','doctor','aurora','sandstone','blueprint','botanical','neon'],true)?$p['theme']:'classic';$accent=preg_match('/^#[0-9a-f]{6}$/i',$p['accent'])?$p['accent']:'#696cff';$background=$p['background_image']?'url("'.sc_url('uploads/'.rawurlencode(basename($p['background_image']))).'")':'none';return '<link rel="stylesheet" href="'.sc_url('assets/css/admin-appearance.css').'?v=5"><script>document.documentElement.dataset.adminTheme='.json_encode($theme).';</script><style>:root{--admin-accent:'.$accent.';--admin-background:'.$background.'}</style>';}
